INSERT INTO `raw_signal` VALUES ('signal_5d4828acfe0b4d75990dab9001d0887b', 'batch_ec2e79957e2a4b4a964e2f785efd3163', 'hn:47881809', 'https://ghostvm.org/', 'CarolineWang', '2026-04-24 04:54:44', 'en', 'Show HN: macOS VMs to let you agents run wild', 'Show HN: macOS VMs to let you agents run wild\n\nShow HN: macOS VMs to let you agents run wild\n\niCloud login works, but i’ve had it log me out randomly. AppStore is straight up blocked. Thankfully Xcode has a manual download. Signing&#x2F;notarization workflows work fine. What did you experience?\n\nHacker News comment query: manual workflow\n\nhttps://ghostvm.org/', '0ee669d07f851753c381585113aaaebbc7ecbcd6121123be5943efb2d1b35312', 'external:hn:47881809', 1, 'signal_fe6662531e234ed487f7083b89ab5207', NULL, '{\"query\": \"manual workflow\", \"has_note\": true, \"platform\": \"hacker_news\", \"item_type\": \"comment\", \"batch_label\": \"Hacker News auto discovery\", \"has_content\": true, \"import_type\": \"link\", \"import_channel\": \"manual\", \"batch_item_index\": 1}', '2026-04-26 14:22:07');
